/* Local-only usage log — the client half of the fleet usage-log convention.
 *
 * VENDORED VERBATIM from project-scaffolding. Do NOT edit this file per-app:
 * per-app variation is markup (`data-track` ids, view ids) and the options
 * passed at the call site. The server half is src/usage_log.py (FastAPI
 * router, POST /api/usage/events + GET /api/usage/summary).
 *
 * Records which views and controls are used, and on which device class, so
 * design reviews read data instead of asking. Events are batched and sent to
 * the app's OWN origin only, never to any other host.
 *
 * Privacy is the contract. Never log message contents, document text,
 * transcripts, names, file names, search queries, form values, URLs with
 * query strings, IP addresses, or the raw user-agent. Only: event kind, view
 * id, control id, a random per-visit session id, device class, and
 * timestamps. Control ids are developer-chosen constants in `data-track`,
 * never derived from element text or user data.
 *
 * Markup contract:
 *   <button data-track="refresh-all">…</button>   a tap on it (or inside it)
 *                                                  records control id
 *                                                  "refresh-all"
 * Wiring:
 *   const usage = initUsageLog();
 *   initNavTabs({ storageKey: 'app.tab', onChange: usage.trackView });
 *   usage.trackView('settings-sheet');             // a sheet/dialog opening
 *
 * An app whose API sits behind a token passes it through `opts.headers`
 * (an object, or a function called per send), never by wrapping `fetch`.
 *
 * Instrumentation never breaks the app: every failure (no endpoint, network
 * error, 4xx/5xx, storage blocked) is swallowed silently.
 */

'use strict';

const DEFAULT_ENDPOINT = '/api/usage/events';
// Mirrors src/usage_log.py ID_PATTERN: bounded, no whitespace, no "/".
const ID_PATTERN = /^[A-Za-z0-9][A-Za-z0-9._:-]{0,63}$/;
// Mirrors src/usage_log.py MAX_EVENTS_PER_BATCH.
const MAX_BATCH = 50;

function randomSessionId() {
  try {
    if (crypto.randomUUID) return crypto.randomUUID();
    const bytes = crypto.getRandomValues(new Uint8Array(16));
    return Array.from(bytes, function (b) { return b.toString(16).padStart(2, '0'); }).join('');
  } catch (_) {
    return 'nocrypto-' + Math.random().toString(36).slice(2, 12);
  }
}

/** `phone | tablet | desktop` from the pointer type and the short screen side
 *  (orientation-independent, so a landscape phone stays a phone). */
export function deviceClass() {
  try {
    const coarse = window.matchMedia('(pointer: coarse)').matches;
    if (!coarse) return 'desktop';
    const shortSide = Math.min(window.screen.width, window.screen.height);
    return shortSide < 600 ? 'phone' : 'tablet';
  } catch (_) {
    return 'desktop';
  }
}

/** `ios | android | windows | other` — the only thing read from the UA, which
 *  itself is never sent. */
export function osClass() {
  const ua = navigator.userAgent || '';
  if (/iPhone|iPad|iPod/.test(ua) || (/Macintosh/.test(ua) && navigator.maxTouchPoints > 1)) return 'ios';
  if (/Android/.test(ua)) return 'android';
  if (/Windows/.test(ua)) return 'windows';
  return 'other';
}

function noop() {}

/**
 * Start recording for this page visit.
 *
 * @param {object} [opts]
 * @param {string} [opts.endpoint='/api/usage/events']  same-origin path. Must
 *   start with a single "/"; anything else (an absolute or protocol-relative
 *   URL) disables the logger with a console warning — it never sends off-origin.
 * @param {number} [opts.flushMs=10000]  send the queue at most this often.
 * @param {object|function(): object} [opts.headers]  extra request headers for
 *   an authenticated endpoint (e.g. `() => ({ Authorization: 'Bearer ' + t })`).
 *   A function is called on every send, so a rotating token is read fresh. A
 *   beacon cannot carry headers, so when this is given the page-hide send is a
 *   `keepalive` fetch instead. Omitted, sends are unchanged.
 * @param {Document|HTMLElement} [opts.root=document]  where the delegated
 *   `data-track` tap listener is attached.
 * @returns {{ trackView: (id: string) => void, flush: () => void,
 *   currentView: () => string|null }}  `trackView` is safe to pass straight
 *   to initNavTabs's `onChange`; `flush` sends the queue now.
 */
export function initUsageLog(opts = {}) {
  const {
    endpoint = DEFAULT_ENDPOINT,
    flushMs = 10000,
    headers = null,
    root = document,
  } = opts;
  const hasHeaders = typeof headers === 'function' || (headers !== null && typeof headers === 'object');

  if (typeof endpoint !== 'string' || endpoint[0] !== '/' || endpoint[1] === '/') {
    console.warn('usage-log: endpoint must be a same-origin path like "/api/usage/events"; logging disabled');
    return { trackView: noop, flush: noop, currentView: function () { return null; } };
  }

  const envelope = {
    session_id: randomSessionId(),
    device_class: deviceClass(),
    os_class: osClass(),
  };
  let queue = [];
  let view = null;
  let timer = null;

  function extraHeaders() {
    try {
      const h = typeof headers === 'function' ? headers() : headers;
      return h && typeof h === 'object' ? h : {};
    } catch (_) { return {}; }
  }

  function send(events, beacon) {
    const body = JSON.stringify(Object.assign({}, envelope, { events: events }));
    try {
      if (beacon && !hasHeaders && navigator.sendBeacon) {
        if (navigator.sendBeacon(endpoint, new Blob([body], { type: 'application/json' }))) return;
      }
      fetch(endpoint, {
        method: 'POST',
        headers: Object.assign({}, extraHeaders(), { 'Content-Type': 'application/json' }),
        body: body,
        credentials: 'same-origin',
        keepalive: true,
      }).catch(noop);
    } catch (_) { /* never break the app */ }
  }

  function flush(beacon) {
    if (timer) { clearTimeout(timer); timer = null; }
    while (queue.length) send(queue.splice(0, MAX_BATCH), beacon === true);
  }

  function push(event) {
    queue.push(event);
    if (queue.length >= MAX_BATCH) { flush(false); return; }
    if (!timer) timer = setTimeout(function () { timer = null; flush(false); }, flushMs);
  }

  function trackView(id) {
    if (typeof id !== 'string' || !ID_PATTERN.test(id)) return;
    view = id;
    push({ kind: 'view', id: id });
  }

  function onTap(e) {
    const target = e.target && e.target.closest ? e.target.closest('[data-track]') : null;
    if (!target) return;
    const id = target.getAttribute('data-track');
    if (!ID_PATTERN.test(id || '')) return;
    const event = { kind: 'tap', id: id };
    if (view) event.view = view;
    push(event);
  }

  try {
    root.addEventListener('click', onTap, true);
    document.addEventListener('visibilitychange', function () {
      if (document.visibilityState === 'hidden') {
        push({ kind: 'session_end' });
        flush(true);
      } else {
        push({ kind: 'session_start' });
      }
    });
    window.addEventListener('pagehide', function () { flush(true); });
  } catch (_) { /* never break the app */ }

  push({ kind: 'session_start' });

  return {
    trackView: trackView,
    flush: function () { flush(false); },
    currentView: function () { return view; },
  };
}
